export const defaults={voc:24,isc:.8,shape:12,g0:1000,g1:450,temp:25,profile:'step',duration:12,dt:.1,tau:.08,step:.24,noise:0,epsilon:0,seed:42,ratio:1/3,bus:5,cap:47,k:1,rfast:.15,fmin:1,fmax:100,finit:12};
export const limits={voc:[12,40],isc:[.1,3],shape:[6,24],g0:[0,1361],g1:[0,1361],temp:[-20,90],duration:[4,60],dt:[.02,.5],tau:[.01,.5],step:[.05,1],noise:[0,3],epsilon:[0,.3],seed:[1,99999],ratio:[.125,8],bus:[1,30],cap:[10,220],k:[.1,5],rfast:[.01,2],fmin:[.1,20],fmax:[25,200],finit:[.1,200]};
export const multipliers=[-3,-1,0,1,3];
export const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
export function validate(p){for(const [k,[lo,hi]] of Object.entries(limits))if(!Number.isFinite(p[k])||p[k]<lo||p[k]>hi)throw Error(`Invalid ${k}: expected ${lo} to ${hi}.`);if(!['constant','step','eclipse'].includes(p.profile))throw Error('Unknown irradiance profile.');if(p.fmin>=p.fmax||p.finit<p.fmin||p.finit>p.fmax)throw Error('Initial frequency must be between the minimum and maximum.');return p;}
export function rng(seed){let s=seed>>>0;return ()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};}
export function irradiance(t,p){if(p.profile==='constant')return p.g0;if(p.profile==='step')return t<p.duration*.45?p.g0:p.g1;return t<p.duration*.35||t>=p.duration*.7?p.g0:0;}
export function panel(g,p){if(g<=0)return {voc:0,isc:0,shape:p.shape,vmp:0,pmp:0};const voc=p.voc*Math.max(.4,1+.036*Math.log(g/1000)-.0025*(p.temp-25));const isc=p.isc*g/1000*Math.max(.1,1+.0005*(p.temp-25));const vmp=voc/Math.pow(p.shape+1,1/p.shape);return {voc,isc,shape:p.shape,vmp,pmp:vmp*isc*p.shape/(p.shape+1)};}
export function current(v,pv){return pv.voc>0?pv.isc*Math.max(0,1-Math.pow(clamp(v/pv.voc,0,1),pv.shape)):0;}
export function resistance(f,p){return p.rfast+p.k/(f*1000*p.cap*1e-6);}
export function equilibrium(f,pv,p){if(!pv.voc)return 0;if(p.bus/p.ratio>=pv.voc)return pv.voc;const r=resistance(f,p);let lo=p.bus/p.ratio,hi=pv.voc;for(let n=0;n<35;n++){const mid=(lo+hi)/2;const eq=p.ratio*(p.ratio*mid-p.bus)/r-current(mid,pv);if(eq>0)hi=mid;else lo=mid;}return (lo+hi)/2;}
export function frequencyFor(vref,pv,p){if(!pv.voc)return p.fmin;const i=current(vref,pv);if(vref<=p.bus/p.ratio)return p.fmax;if(i<1e-8)return p.fmin;const req=p.ratio*(p.ratio*vref-p.bus)/i;if(req<=p.rfast)return p.fmax;return clamp(p.k/((req-p.rfast)*p.cap*1e-6)/1000,p.fmin,p.fmax);}
export function forward(state,policy){let a=state;for(let l=0;l<policy.weights.length;l++){const w=policy.weights[l],b=policy.biases[l];const z=b.map((x,j)=>x+a.reduce((sum,v,i)=>sum+v*w[i][j],0));a=l===policy.weights.length-1?z:z.map(x=>Math.max(0,x));}return a;}
export function metrics(rows,p){let ep=0,eb=0,em=0,er=0;for(let i=0;i<rows.length-1;i++){const h=rows[i+1].t-rows[i].t;for(const [key,add] of [['p',x=>ep+=x],['busP',x=>eb+=x],['pmp',x=>em+=x],['reachable',x=>er+=x]])add((rows[i][key]+rows[i+1][key])*h/2);}
 const lastStart=p.profile==='constant'?0:p.duration*(p.profile==='step'?.45:.7);const last=rows.filter(x=>x.t>=Math.max(lastStart,p.duration*.8)&&x.pmp>1e-8);const powers=last.map(x=>x.p).sort((a,b)=>a-b);const ripple=powers.length?powers[Math.floor((powers.length-1)*.95)]-powers[Math.floor((powers.length-1)*.05)]:null;
 const final=rows.filter(x=>x.t>=lastStart);let settling=null;if(final.length&&final.at(-1).pmp>1e-8){let bad=-1;final.forEach((x,i)=>{if(x.pmp<1e-8||Math.abs(x.p-x.pmp)/x.pmp>.02)bad=i;});const candidate=final[bad+1];if(candidate&&final.at(-1).t-candidate.t>=.5)settling=candidate.t-lastStart;}
 return {tracking:em>1e-9?100*ep/em:null,pvEnergy:ep,busEnergy:eb,conversion:ep>1e-9?100*eb/ep:null,reachable:em>1e-9?100*er/em:null,settling,ripple};}
export function simulate(p,policy){validate(p);if(!policy?.weights)throw Error('DQN policy is not loaded.');const randomNoise=rng(p.seed),randomAction=rng(p.seed+7301);const states=['po','dqn'].map(name=>{const pv=panel(p.g0,p);const v=equilibrium(p.finit,pv,p);return {name,v,ref:v,oldV:v,oldP:v*current(v,pv),dir:1,rows:[],lastAction:0};});
 const count=Math.ceil(p.duration/p.dt);for(let n=0;n<=count;n++){const t=Math.min(n*p.dt,p.duration),pv=panel(irradiance(t,p),p);const nv=(randomNoise()-.5)*2*p.noise/100,ni=(randomNoise()-.5)*2*p.noise/100;for(const s of states){let f=clamp(p.finit,p.fmin,p.fmax);if(n){f=frequencyFor(s.ref,pv,p);const h=t-s.rows.at(-1).t;s.v=clamp(s.v+(equilibrium(f,pv,p)-s.v)*(1-Math.exp(-h/p.tau)),0,pv.voc);}
 const i=current(s.v,pv),power=s.v*i,vm=s.v*(1+nv),im=i*(1+ni),pm=vm*im;const vmin=equilibrium(p.fmax,pv,p),vmax=equilibrium(p.fmin,pv,p);const vr=clamp(pv.vmp,vmin,vmax);const reachable=vr*current(vr,pv);const ratio=p.ratio*s.v;const busP=ratio>p.bus?power*p.bus/ratio:0;
 const obs=[vm/p.voc,im/p.isc,(pm-s.oldP)/(p.voc*p.isc)*5,(vm-s.oldV)/p.voc*5,s.ref/p.voc];const q=s.name==='dqn'?forward(obs,policy):null;
 s.rows.push({t,g:irradiance(t,p),v:s.v,i,p:power,pmp:pv.pmp,vmp:pv.vmp,f,busP,reachable,ref:s.ref,action:s.lastAction,q});
 if(pv.pmp>1e-8){if(s.name==='po'){if(n){const dp=pm-s.oldP,dv=vm-s.oldV;if(Math.abs(dp)>1e-9&&Math.abs(dv)>1e-9)s.dir=dp*dv>=0?1:-1;}s.lastAction=s.dir;s.ref+=s.dir*p.step;}else{let a=q.indexOf(Math.max(...q));if(randomAction()<p.epsilon)a=Math.floor(randomAction()*5);s.lastAction=multipliers[a];s.ref+=s.lastAction*p.step;}s.ref=clamp(s.ref,.25*p.voc,1.1*p.voc);}else{s.lastAction=0;s.ref=p.voc*.8;}
 s.oldV=vm;s.oldP=pm;
 }}return {params:{...p},po:states[0].rows,dqn:states[1].rows,metrics:{po:metrics(states[0].rows,p),dqn:metrics(states[1].rows,p)},policy:policy.metadata};}
export function domainWarnings(p){const checks=[[p.voc,22,26,'Voc'],[p.isc,.6,1.2,'Isc'],[p.shape,8,16,'curve shape'],[p.temp,0,70,'temperature'],[p.cap,30,80,'transfer capacitance'],[p.bus,4.5,5.5,'bus voltage'],[p.tau,.02,.15,'response time']];const outside=checks.filter(([v,a,b])=>v<a||v>b).map(x=>x[3]);if(Math.abs(p.ratio-1/3)>1e-5)outside.push('conversion ratio');if(p.noise>0)outside.push('sensor noise');if(Math.abs(p.dt-.1)>1e-6)outside.push('sample period');if(Math.abs(p.step/p.voc-.01)>.001)outside.push('action step');if(p.rfast!==.15||p.k!==1||p.fmin!==1||p.fmax!==100)outside.push('converter loss or frequency limits');if(p.g0<200||p.g0>1200||(p.profile==='step'&&(p.g1<200||p.g1>1200))||p.profile==='eclipse')outside.push('irradiance');return outside;}
